using namespace rb;
using Clock=std::chrono::steady_clock;
inline void barrier(){asm volatile("":::"memory");}
template<class T>inline void observe(const T&x){asm volatile(""::"g"(&x):"memory");}
struct Case{std::string name;size_t pieces,first;bool shuffled;float radius,minwidth;};
struct Timing{uint64_t reps=1;std::vector<double>samples;double median=0,p25=0,p75=0;};
struct Variant{std::string name;Options options;std::function<void()>fn;std::function<std::pair<uint64_t,Stats>()>check;Timing timing;};
template<class S>Variant variant(std::string name,Options o,const World&w,const S&source,const Case&c,const Prebuilt&cache){auto work=std::make_shared<Work<S>>();auto run=[&,work,o]{run_event(w,source,0,Blast{{-3.8f,.2f},c.radius},o,c.minwidth,*work,o.prebuilt?&cache:nullptr);};Variant v;v.name=std::move(name);v.options=o;v.fn=[&,work,o,run]{if(o.reuse){run();observe(*work);}else{Work<S>fresh;run_event(w,source,0,Blast{{-3.8f,.2f},c.radius},o,c.minwidth,fresh,o.prebuilt?&cache:nullptr);observe(fresh);}};v.check=[&,work,run]{run();validate(w,*work);return std::pair{signature(w,*work),work->stats};};return v;}
double run_n(const std::function<void()>&f,uint64_t n){barrier();auto a=Clock::now();for(uint64_t i=0;i<n;++i){f();barrier();}return std::chrono::duration<double,std::nano>(Clock::now()-a).count();}
void measure(std::vector<Variant>&v,double target_ms){for(auto&x:v){for(int k=0;k<3;++k)x.fn();while(run_n(x.fn,x.timing.reps)<target_ms*1e6&&x.timing.reps<(1ULL<<24))x.timing.reps*=2;}std::mt19937 rng(97123);std::vector<size_t>order(v.size());std::iota(order.begin(),order.end(),0);for(int round=0;round<9;++round){std::shuffle(order.begin(),order.end(),rng);for(auto i:order)v[i].timing.samples.push_back(run_n(v[i].fn,v[i].timing.reps)/v[i].timing.reps);}for(auto&x:v){auto a=x.timing.samples;std::sort(a.begin(),a.end());x.timing.median=a[4];x.timing.p25=a[2];x.timing.p75=a[6];}}
void output_timing(std::ostream&f,const Timing&t){f<<t.median<<','<<t.p25<<','<<t.p75<<','<<t.reps;for(double x:t.samples)f<<','<<x;}
void timing_header(std::ostream&f){f<<"median_ns,p25_ns,p75_ns,repetitions";for(int i=0;i<9;++i)f<<",sample_"<<i<<"_ns";}

template<class S>uint64_t hot_query(const World&w,const S&s,uint32_t selected,Blast b,bool members){uint64_t sum=0;if(members){float strength=w.materials[w.pieces[selected].material].subdivision_strength;for(uint32_t i:w.pieces[selected].members)if(fails(load(b,s.position(i)),strength))sum+=hash64(s.id(i));}else{for(size_t i=0;i<s.size();++i)if(s.owner(i)==selected){float strength=w.materials[w.pieces[s.owner(i)].material].subdivision_strength;if(fails(load(b,s.position(i)),strength))sum+=hash64(s.id(i));}}return sum;}
template<class S>Variant query_variant(std::string name,const World&w,const S&s,bool members,bool whole){Variant v;v.name=name;v.fn=[&,members,whole]{uint64_t h=0;if(whole&&members){for(uint32_t owner=0;owner<w.pieces.size();++owner){auto&pc=w.pieces[owner];float strength=w.materials[pc.material].subdivision_strength;Blast b{{-3.8f+16.f*float(owner%128),.2f+16.f*float(owner/128)},5.8f};for(auto i:pc.members)if(fails(load(b,s.position(i)),strength))h+=hash64(s.id(i));}}else if(whole){for(size_t i=0;i<s.size();++i){auto owner=s.owner(i);Blast b{{-3.8f+16.f*float(owner%128),.2f+16.f*float(owner/128)},5.8f};if(fails(load(b,s.position(i)),w.materials[w.pieces[owner].material].subdivision_strength))h+=hash64(s.id(i));}}else h=hot_query(w,s,0,{{-3.8f,.2f},5.8f},members);observe(h);};return v;}

void geometry_checks(){std::vector<Poly>shapes={{{0,0},{2,0},{2,1},{1,1},{1,2},{0,2}},{{0,0},{3,0},{3,1},{0,1}},{{0,0},{.005f,0},{.005f,.005f},{0,.005f}}};for(auto&p:shapes){if(!simple(p))throw std::runtime_error("bad property input");if(width(p)<=.09f)continue;for(int k=0;k<3;++k)for(int seed:{1,7,42,255}){Recipe r{4,6,.25f,uint32_t(k==0?3:k==1?5:6),k==1?.2f:1.f,k==2};auto c=generate(p,r,uint8_t(seed));if(c.empty())continue;double a=0;for(auto&q:c){if(!simple(q))throw std::runtime_error("generator self intersection");a+=area(q);}if(std::abs(a-area(p))>std::max(2e-6,area(p)*2e-4))throw std::runtime_error("coverage check");}}Poly p{{0,0},{2,0},{2,1},{0,1}},rot;float a=.738f;for(V v:p)rot.push_back({v.x*std::cos(a)-v.y*std::sin(a),v.x*std::sin(a)+v.y*std::cos(a)});if(std::abs(width(p)-width(rot))>1e-5)throw std::runtime_error("rotation width check");}

int main(int argc,char**argv){try{bool verify=argc>1&&std::string(argv[1])=="--verify-only";Templates input=read_templates("inputs/templates.txt");geometry_checks();std::ofstream out(verify?"results/verification.csv":"results/events.csv");out<<std::setprecision(12);out<<"case,pieces,source_nodes,shuffled,variant,";if(!verify){timing_header(out);out<<',';}out<<"checksum,evaluated,generated,refinements,dropped,pruned,width_calls,edge_queries,edge_derivations,anchor_builds,cache_hits,final_nodes,final_edges,groups,fading,impulses,max_depth,peak_pending,storage_bytes\n";
 std::vector<Case>cases={{"chunk_boundary",8,0,false,5.8f,.18f},{"splinter_boundary",8,1,false,6.2f,.18f},{"shatter_boundary",8,2,false,5.5f,.18f},{"chunk_deep",8,0,false,6.5f,.09f},{"whole_piece_erased",1,0,false,12.f,.18f},{"terminal_seed_zero",8,3,false,6.5f,.18f},{"sparse_512_shuffled",512,0,true,5.8f,.18f},{"sparse_8192_shuffled",8192,0,true,5.8f,.18f}};
 std::ofstream stages(verify?"results/verification-stage-header.csv":"results/stages.csv");stages<<std::setprecision(12)<<"case,stage,median_ns,p25_ns,p75_ns,repetitions";for(int i=0;i<9;++i)stages<<",sample_"<<i<<"_ns";stages<<"\n";
 std::ofstream queries;if(!verify){queries.open("results/queries.csv");queries<<std::setprecision(12)<<"case,pieces,source_nodes,whole_world,variant,";timing_header(queries);queries<<"\n";}
 for(auto&c:cases){std::cerr<<"begin "<<c.name<<"\n";World w=make_world(input,c.pieces,c.first,c.shuffled);AoS a=make_store<AoS>(w);PoseFirst p=make_store<PoseFirst>(w);HotCold h=make_store<HotCold>(w);Columns s=make_store<Columns>(w);Prebuilt cache=prebuild(w,0,c.minwidth);std::vector<Variant>v;Options o;v.push_back(variant("aos_context",o,w,a,c,cache));v.push_back(variant("aos_pose_first",o,w,p,c,cache));v.push_back(variant("hot_cold",o,w,h,c,cache));v.push_back(variant("hot_columns",o,w,s,c,cache));o.dfs=true;v.push_back(variant("depth_first",o,w,a,c,cache));o={};o.cached_width=false;v.push_back(variant("derive_width",o,w,a,c,cache));o={};o.shared_seed=false;v.push_back(variant("per_child_common_check",o,w,a,c,cache));o={};o.anchors=Cache::Geometry;v.push_back(variant("derive_anchors",o,w,a,c,cache));o={};o.anchors=Cache::BirthFinal;v.push_back(variant("survivor_anchors",o,w,a,c,cache));o={};o.rescan=true;v.push_back(variant("rescan_edges_each_wave",o,w,a,c,cache));o={};o.reuse=false;v.push_back(variant("fresh_work_buffers",o,w,a,c,cache));o={};o.wipe_prune=true;v.push_back(variant("skip_fully_erased",o,w,a,c,cache));o={};o.prebuilt=true;v.push_back(variant("prebuilt_next_generation",o,w,a,c,cache));o={};o.global_scan=true;v.push_back(variant("scan_global_owners",o,w,a,c,cache));o={};o.broadcast=false;v.push_back(variant("lookup_material",o,w,a,c,cache));o={};o.recursive=false;v.push_back(variant("one_generation_control",o,w,a,c,cache));o={};v.push_back(variant("aos_duplicate_control",o,w,a,c,cache));o={};o.wipe_prune=true;v.push_back(variant("pruned_pose_first",o,w,p,c,cache));v.push_back(variant("pruned_hot_cold",o,w,h,c,cache));v.push_back(variant("pruned_hot_columns",o,w,s,c,cache));v.push_back(variant("pruned_duplicate_control",o,w,a,c,cache));o.anchors=Cache::BirthFinal;v.push_back(variant("pruned_survivor_anchors",o,w,a,c,cache));o.anchors=Cache::LocalAll;o.cached_width=false;v.push_back(variant("pruned_derive_width",o,w,a,c,cache));o.cached_width=true;o.dfs=true;v.push_back(variant("pruned_depth_first",o,w,a,c,cache));o.dfs=false;o.prebuilt=true;v.push_back(variant("pruned_prebuilt",o,w,a,c,cache));o.prebuilt=false;o.global_scan=true;v.push_back(variant("pruned_global_scan",o,w,a,c,cache));
  uint64_t expected=v[0].check().first;for(auto&x:v){auto [sig,stats]=x.check();if(x.options.recursive&&sig!=expected){std::cerr<<"DIFFERENT "<<c.name<<' '<<x.name<<' '<<sig<<" != "<<expected<<'\n';return 2;}}if(!verify)measure(v,3.0);for(auto&x:v){auto [sig,z]=x.check();if(x.options.recursive&&sig!=expected)throw std::runtime_error("post timing output mismatch");out<<c.name<<','<<c.pieces<<','<<w.source.size()<<','<<c.shuffled<<','<<x.name<<',';if(!verify){output_timing(out,x.timing);out<<',';}out<<sig<<','<<z.evaluated<<','<<z.generated<<','<<z.refinements<<','<<z.dropped<<','<<z.pruned<<','<<z.width_calls<<','<<z.edge_queries<<','<<z.edge_derivations<<','<<z.anchor_builds<<','<<z.cache_hits<<','<<z.final_nodes<<','<<z.final_edges<<','<<z.groups<<','<<z.fading<<','<<z.impulses<<','<<z.max_depth<<','<<z.peak_pending<<','<<z.storage_bytes<<'\n';}out.flush();if(!verify){Work<AoS>work;Options prof;prof.profile=true;for(int k=0;k<3;++k)run_event(w,a,0,{{-3.8f,.2f},c.radius},prof,c.minwidth,work);size_t reps=std::max<uint64_t>(1,v[0].timing.reps);std::array<std::vector<double>,3>times;for(int round=0;round<9;++round){std::array<double,3>tot{};for(size_t k=0;k<reps;++k){run_event(w,a,0,{{-3.8f,.2f},c.radius},prof,c.minwidth,work);tot[0]+=work.stats.prepare_ns;tot[1]+=work.stats.geometry_ns;tot[2]+=work.stats.update_ns;observe(work);}for(int j=0;j<3;++j)times[j].push_back(tot[j]/reps);}for(int j=0;j<3;++j){auto z=times[j];std::sort(z.begin(),z.end());stages<<c.name<<','<<(j==0?"prepare_and_old_edges":j==1?"node_loads_and_generation":"connections_groups_filter_impulses")<<','<<z[4]<<','<<z[2]<<','<<z[6]<<','<<reps;for(auto x:times[j])stages<<','<<x;stages<<'\n';}stages.flush();}std::cerr<<"checked "<<c.name<<" ("<<w.source.size()<<" original nodes)\n";
  if(!verify&&(c.name=="chunk_boundary"||c.shuffled)){for(bool whole:{false,true}){std::vector<Variant>q;q.push_back(query_variant("aos_owner",w,a,false,whole));q.push_back(query_variant("pose_first_owner",w,p,false,whole));q.push_back(query_variant("hot_cold_owner",w,h,false,whole));q.push_back(query_variant("hot_columns_owner",w,s,false,whole));q.push_back(query_variant("aos_members",w,a,true,whole));q.push_back(query_variant("hot_columns_members",w,s,true,whole));if(!whole){auto x=hot_query(w,a,0,{{-3.8f,.2f},5.8f},false);if(hot_query(w,a,0,{{-3.8f,.2f},5.8f},true)!=x||hot_query(w,s,0,{{-3.8f,.2f},5.8f},false)!=x)throw std::runtime_error("selection outputs differ");}measure(q,3);for(auto&x:q){queries<<c.name<<','<<c.pieces<<','<<w.source.size()<<','<<whole<<','<<x.name<<',';output_timing(queries,x.timing);queries<<'\n';}queries.flush();}}
 }
 if(!verify){std::ofstream costs("results/construction.csv");costs<<std::setprecision(12)<<"case,variant,cache_entries,cache_bytes,";timing_header(costs);costs<<"\n";for(size_t ti:{0U,1U,2U}){World w=make_world(input,1,ti,false);auto pc=w.pieces[0];Prebuilt example=prebuild(w,0,.18f);Poly all;for(auto i:pc.members){auto pp=w.outline(w.source[i]);all.insert(all.end(),pp.begin(),pp.end());}Poly parent=hull(all);Batch initial=make_batch(parent,w.materials[pc.material],pc.seed);size_t initial_bytes=sizeof(Batch)+initial.widths.capacity()*4+initial.pairs.capacity()*sizeof(PairMid);for(auto&pp:initial.p)initial_bytes+=sizeof(Poly)+pp.capacity()*sizeof(V);std::vector<Variant>v;Variant x;x.name="initial_graph";x.fn=[&]{auto b=make_batch(parent,w.materials[pc.material],pc.seed);std::vector<uint8_t>seeds(b.p.size());float mx=*std::max_element(b.widths.begin(),b.widths.end());bool can=pc.seed&&mx>.18f;for(size_t j=0;j<seeds.size();++j)seeds[j]=can?seed_for(pc.seed,child_id(1,j)):0;observe(b);observe(seeds);};v.push_back(x);x.name="next_generation_cache";x.fn=[&]{auto c=prebuild(w,0,.18f);observe(c);};v.push_back(x);x.name="width_cache";x.fn=[&]{float total=0;for(auto i:pc.members)total+=width(w.outline(w.source[i]));observe(total);};v.push_back(x);x.name="local_anchor_cache";x.fn=[&]{std::vector<Anchor>out;out.reserve(pc.edges.size());for(auto e:pc.edges){Node a=w.source[e.a],b=w.source[e.b];auto sh=shared(w.outline(a),w.outline(b));out.push_back({sh.point-a.rest,sh.point-b.rest});}observe(out);};v.push_back(x);measure(v,3);for(auto&z:v){costs<<ti<<','<<z.name<<','<<(z.name=="initial_graph"?initial.p.size():z.name=="next_generation_cache"?example.size():z.name=="width_cache"?pc.members.size():pc.edges.size())<<','<<(z.name=="initial_graph"?initial_bytes:z.name=="next_generation_cache"?prebuilt_bytes(example):z.name=="width_cache"?pc.members.size()*4:pc.edges.size()*sizeof(Anchor))<<',';output_timing(costs,z.timing);costs<<'\n';}}}
 std::cerr<<"all checks passed\n";
 }catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 1;}}
